      (res) => {
        if (id !== latestRequest.current) return;
        setResponse(res);
        setError(null);
        setPending(false);
      },
      (err: unknown) => {
        if (id !== latestRequest.current) return;
        setError(err instanceof Error ? err.message : String(err));
        setPending(false);
