    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      timer.current = null;
      setPending(true);
      request(next);
    }, DEBOUNCE_MS);
  }

  return (
    <div className="mx-auto grid w-full max-w-6xl gap-8 px-4 py-6 sm:px-6 md:grid-cols-[16rem_minmax(0,1fr)] md:py-10">
